do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('PAR-4', 'fkt_quadr_parabel', 'fkt_quadr_parabel:K3', 'feldmaske', '{uebung,transfer}'::text[],
        '{"text": "Die Normalparabel wird {wie}. Gib die Gleichung der neuen Parabel an.", "stufen": {"2": "nach rechts und nach oben, je 1 bis 8", "3": "nach links oder nach unten", "4": "zusätzlich mit dem Faktor 2, 3 oder 1/2 gestreckt bzw. gestaucht"}, "fehlbilder": [{"key": "qf_verschiebung_vorzeichen", "regel": "(x + d)² für „nach rechts“", "gilt_fuer_stufen": [2, 3, 4], "rueckmeldung": "Nach rechts heißt: Die Klammer wird erst für ein positives x null. Also (x − d)."}, {"key": "qf_d_e_vertauscht", "regel": "d und e vertauscht", "gilt_fuer_stufen": [2, 3, 4], "rueckmeldung": "Die Verschiebung nach rechts oder links steht in der Klammer, nach oben oder unten steht hinten."}, {"key": "qf_streckfaktor_vergessen", "regel": "a vergessen", "gilt_fuer_stufen": [4], "rueckmeldung": "Die Parabel ist auch gestreckt oder gestaucht. Diese Zahl steht vor der Klammer."}], "hinweise": ["Die Scheitelpunktform ist f(x) = a(x − d)² + e.", "Wo liegt der neue Scheitel?", "Setz den Scheitel S(d | e) in die Scheitelpunktform ein."], "loesungsweg": [], "warum": null, "kontext": null, "figur": null, "zeit_sek": 60, "kann_entfallen": false, "generator_hash": "afb11f4d592b"}'::jsonb, 'scripts/bauformen/bauformen/par_4.py', 'zur_pruefung',
